export const fitLevels092=[{id:'best',label:'Best fit'},{id:'good',label:'Good fit'},{id:'overlap',label:'Some overlap'},{id:'explore',label:'Explore further'}];
export function fitLevel092(value){return Number.isFinite(value)?value>=.729?'best':value>=.608?'good':value>=0?'overlap':'explore':'explore';}
export function fitGroups092(row){const all=[...row.supported,...row.candidates],seen=new Set();return fitLevels092.map(level=>({...level,offers:all.filter(o=>{if(seen.has(o.id)||(o.fitLevel||fitLevel092(o.correlation))!==level.id)return false;seen.add(o.id);return true;}).sort((a,b)=>(Number.isFinite(b.correlation)?b.correlation:-2)-(Number.isFinite(a.correlation)?a.correlation:-2)||Number(!!b.top)-Number(!!a.top)||a.title.localeCompare(b.title))}));}
export function hydrateCurrent092(data){return data.rows.map(r=>({...r,supported:r.supported.map(([id,top,lifestyleCovers,correlation,fitLevel])=>({...data.catalog[data.careerIds?.[id]??id],top,lifestyleCovers,correlation:correlation==null?null:correlation/(data.correlationScale||1),fitLevel,candidate:false})),candidates:r.candidates.map(value=>{const[id,correlation,mixedInterests,fitLevel]=Array.isArray(value)?value:[value,null,false];return{...data.catalog[data.careerIds?.[id]??id],correlation:correlation==null?null:correlation/(data.correlationScale||1),mixedInterests,fitLevel,candidate:true};})}));}
export function currentStatistics092(rows){const degree=o=>o.routes.some(r=>['college','graduate'].includes(r.key)),noncollege=o=>!degree(o)&&!o.routes.some(r=>r.label.toLowerCase().includes('associate')),top=r=>r.supported.filter(o=>o.top);return{models:rows.length,top:rows.filter(r=>top(r).length).length,degree:rows.filter(r=>top(r).some(degree)).length,noncollege:rows.filter(r=>top(r).some(noncollege)).length,lifestyle:rows.filter(r=>r.supported.some(o=>o.lifestyleCovers===true)).length,unconfirmedOnly:rows.filter(r=>!r.supported.length&&r.candidates.length).length};}
